#!/usr/bin/env bash
set -euo pipefail
out="${1:-visual-review}"; rm -rf "$out"; mkdir -p "$out/png"
labels=("01-connection|شاشة الاتصال|عنوان الراوتر • منفذ API • اسم المستخدم • TLS • حفظ واختبار" "02-dashboard|Smart Manager Dashboard|حالة الاتصال • RouterOS • CPU • Uptime • الوحدات" "03-routers|ملفات الراوترات|إضافة ملف • اختيار نشط • تعديل • حذف" "04-hotspot-users|Hotspot / المستخدمون|تبويبات: المستخدمون • الباقات • الجلسات النشطة • بحث" "05-hotspot-profiles|Hotspot / الباقات|قائمة الباقات • تحديث • تفاصيل" "06-hotspot-active|Hotspot / الجلسات|المستخدم • العنوان • uptime • فصل" "07-pppoe-users|PPPoE / الحسابات|تبويبات: الحسابات • Profiles • Active Sessions" "08-pppoe-profiles|PPPoE / Profiles|الباقة • العناوين • rate-limit" "09-pppoe-active|PPPoE / الجلسات|الاسم • العنوان • الخدمة • فصل" "10-user-manager|User Manager|RouterOS v6/v7 • المستخدمون • الباقات • الجلسات" "11-resource-detail|تفاصيل المورد|الاسم • .id • الباقة • تعديل • تفعيل/تعطيل • حذف" "12-cards|الكروت والدفعات|البادئة • العدد • الباقة • إنشاء • معاينة • PDF" "13-batch-history|سجل الدفعات المشفر|معرف الدفعة • الحالة • الراوتر • مصالحة آمنة" "14-interfaces|الواجهات والإحصاءات|الاسم • الحالة • RX • TX • تحديث" "15-ip|عناوين IP|العنوان • الواجهة • الحالة • بحث" "16-dhcp|DHCP|Servers • Leases • Networks • تحديث" "17-dns|DNS|الإعدادات • Static Entries • قراءة فقط" "18-queues-firewall|Queues وFirewall|Simple Queues • Filter • NAT • Address Lists • Mangle" "19-monitoring-reports|المراقبة والتقارير|CPU • RAM • Storage • Uptime • Hotspot/PPPoE • Interfaces")
for item in "${labels[@]}"; do IFS='|' read -r file title body <<< "$item"
  convert -size 1080x1920 xc:'#EDF4FA' -fill '#162F50' -draw 'rectangle 0,0 1080,120' -fill white -pointsize 38 -gravity NorthEast -annotate +70+42 'Smart Manager' -fill '#1767B1' -pointsize 42 -gravity NorthEast -annotate +70+190 "$title" -fill '#E8F2F8' -draw 'roundrectangle 60,290 1020,378 18,18' -fill '#162F50' -pointsize 26 -gravity NorthEast -annotate +70+325 'DEMO / VISUAL MOCKUP - no real router data' -fill white -draw 'roundrectangle 60,430 1020,670 24,24' -fill '#162F50' -pointsize 32 -gravity NorthEast -annotate +80+500 "$body" -pointsize 25 -gravity NorthEast -annotate +80+585 'RTL - Smart Manager colors - read-only preview' -draw 'roundrectangle 60,730 1020,870 20,20' -pointsize 30 -gravity NorthEast -annotate +80+810 'No live data in this visual review' -draw 'roundrectangle 60,900 1020,1040 20,20' -pointsize 28 -gravity NorthEast -annotate +80+980 'Lists and details appear after a real connection' -fill '#162F50' -draw 'rectangle 0,1800 1080,1920' -fill white -pointsize 24 -gravity SouthEast -annotate +180+35 'Home        Sessions        Cards' "$out/png/$file.png"
done
montage "$out"/png/*.png -thumbnail 180x320 -tile 4x -geometry +12+12 -background '#162F50' "$out/SmartManager-Visual-Contact-Sheet.png"
zip -qr "SmartManager-Android-Visual-Review.zip" "$out"
